import { execFileSync } from 'node:child_process';

const run = (a, b) => {
  try {
    return execFileSync('/workspace/dataset/test7_executable', ['--a', a, '--b', b], { encoding: 'utf8' });
  } catch (e) {
    return 'ERR status=' + e.status + '\n' + (e.stderr || '');
  }
};

const cases = [
  ['U+FFFF vs U+1F600', '￿', '\u{1F600}'],
  ['U+1F600 vs U+FFFF', '\u{1F600}', '￿'],
  ['U+D7FF vs U+10000', '퟿', '\u{10000}'],
  ['lone high surrogate', 'a\uD800b', 'x'],
  ['DEL 0x7f vs 0x80', 'ab', 'cd'],
  ['NUL', 'a�b', 'x'],
  ['0x9f control', 'ab', 'x'],
  ['soft hyphen', 'a­b', 'x'],
  ['BOM', '﻿abc', 'x'],
];

for (const [label, a, b] of cases) {
  console.log('=== ' + label + ' ===');
  console.log(run(a, b));
}

