import { execFileSync } from 'node:child_process';

const run = (...args) => {
  try {
    return 'rc=0 | ' + execFileSync('/workspace/dataset/test7_executable', args, { encoding: 'utf8' }).trim().replace(/\n/g, ' || ');
  } catch (e) {
    return 'rc=' + e.status + ' | ' + (e.stderr || '').trim().split('\n').pop();
  }
};

const cases = [
  ['-hx', ['-hx']],
  ['--help=x', ['--help=x']],
  ['--a 1 --b 2 --c', ['--a', '1', '--b', '2', '--c']],
  ['--b 2 zzz --a 1', ['--b', '2', 'zzz', '--a', '1']],
  ['--a', ['--a']],
  ['-h --nope', ['-h', '--nope']],
  ['--a 1 --b 2 -1', ['--a', '1', '--b', '2', '-1']],
  ['--a=--b --b=2', ['--a=--b', '--b=2']],
  ['empty arg', ['--a', '1', '--b', '2', '']],
];

for (const [label, args] of cases) console.log(label.padEnd(22) + ' -> ' + run(...args));

