/**
 * lib/python/utf8.mjs
 *
 * Hand-rolled UTF-8 codec that mirrors CPython's ``str.encode("utf-8")``.
 *
 * The canonical-JSON encoder produces a *text* document and then hands it to
 * this module, because the reference implementation returns ``bytes`` -- the
 * distinction is visible in the final output, since printing ``bytes`` shows a
 * byte-oriented repr where every non-ASCII code point has become 2-4 escapes.
 */

/** U+FFFD REPLACEMENT CHARACTER. */
export const REPLACEMENT_CODE_POINT = 0xfffd;

const HIGH_SURROGATE_START = 0xd800;
const HIGH_SURROGATE_END = 0xdbff;
const LOW_SURROGATE_START = 0xdc00;
const LOW_SURROGATE_END = 0xdfff;

/**
 * Split a JS string into Unicode code points, the way Python iterates a `str`.
 *
 * JS strings are UTF-16, so an astral character occupies two code units. Every
 * comparison and every encoding step downstream has to work on code points to
 * stay faithful to Python; iterating code units would, for instance, order
 * U+FFFF after an emoji instead of before it.
 *
 * Unpaired surrogates are reported as-is so callers can decide what to do.
 *
 * @param {string} text
 * @returns {number[]}
 */
export function codePointsOf(text) {
  const points = [];
  for (let index = 0; index < text.length; index += 1) {
    const unit = text.charCodeAt(index);
    if (unit >= HIGH_SURROGATE_START && unit <= HIGH_SURROGATE_END && index + 1 < text.length) {
      const trail = text.charCodeAt(index + 1);
      if (trail >= LOW_SURROGATE_START && trail <= LOW_SURROGATE_END) {
        points.push((unit - HIGH_SURROGATE_START) * 0x400 + (trail - LOW_SURROGATE_START) + 0x10000);
        index += 1;
        continue;
      }
    }
    points.push(unit);
  }
  return points;
}

/** True for a code point that can only ever be half of a surrogate pair. */
export function isSurrogate(codePoint) {
  return codePoint >= HIGH_SURROGATE_START && codePoint <= LOW_SURROGATE_END;
}

/**
 * Encode text as UTF-8.
 *
 * Unpaired surrogates are replaced with U+FFFD, which is what the runtime has
 * already done to any malformed argument bytes by the time they reach us: the
 * OS hands over bytes, and an undecodable sequence in `process.argv` surfaces
 * as U+FFFD rather than as a lone surrogate.
 *
 * @param {string} text
 * @returns {Uint8Array}
 */
export function encodeUtf8(text) {
  const bytes = [];
  for (const rawPoint of codePointsOf(text)) {
    const codePoint = isSurrogate(rawPoint) ? REPLACEMENT_CODE_POINT : rawPoint;
    if (codePoint < 0x80) {
      bytes.push(codePoint);
    } else if (codePoint < 0x800) {
      bytes.push(0xc0 | (codePoint >> 6), 0x80 | (codePoint & 0x3f));
    } else if (codePoint < 0x10000) {
      bytes.push(0xe0 | (codePoint >> 12), 0x80 | ((codePoint >> 6) & 0x3f), 0x80 | (codePoint & 0x3f));
    } else {
      bytes.push(
        0xf0 | (codePoint >> 18),
        0x80 | ((codePoint >> 12) & 0x3f),
        0x80 | ((codePoint >> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    }
  }
  return Uint8Array.from(bytes);
}

