/**
 * lib/python/text.mjs
 *
 * Python `str` semantics that JS does not give us for free: code-point
 * ordering (what `sorted()` uses) and `repr()` of a string.
 */

import { codePointsOf } from './utf8.mjs';

/**
 * Compare two strings the way Python's `<` does: code point by code point.
 *
 * JS `<` compares UTF-16 code units, which disagrees with Python whenever one
 * side holds an astral character: '￿' < '\u{1f600}' is true in Python
 * (0xFFFF < 0x1F600) but false in JS (0xFFFF > 0xD83D, the lead surrogate).
 *
 * @returns {number} negative, zero, or positive
 */
export function compareCodePoints(left, right) {
  const a = codePointsOf(left);
  const b = codePointsOf(right);
  const shared = Math.min(a.length, b.length);
  for (let index = 0; index < shared; index += 1) {
    if (a[index] !== b[index]) return a[index] < b[index] ? -1 : 1;
  }
  return a.length - b.length;
}

/**
 * Python's `sorted()` over a list of strings: ascending, stable, new list.
 *
 * @param {string[]} items
 * @returns {string[]}
 */
export function sortedStrings(items) {
  return items
    .map((value, index) => ({ value, index }))
    .sort((x, y) => compareCodePoints(x.value, y.value) || x.index - y.index)
    .map((entry) => entry.value);
}

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\t', '\\t'],
  ['\n', '\\n'],
  ['\r', '\\r'],
]);

/**
 * Python's `repr()` for a string -- used inside argument-parser error text.
 *
 * Only the ASCII range needs faithful treatment here: non-ASCII code points
 * are printable in Python 3 reprs and pass through unescaped.
 */
export function strRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  const parts = ['b'.slice(1), quote];
  for (const character of text) {
    if (character === quote) {
      parts.push('\\', character);
    } else if (SHORT_ESCAPES.has(character)) {
      parts.push(SHORT_ESCAPES.get(character));
    } else if (character.codePointAt(0) < 0x20) {
      parts.push('\\x' + character.codePointAt(0).toString(16).padStart(2, '0'));
    } else {
      parts.push(character);
    }
  }
  parts.push(quote);
  return parts.join('');
}

