/**
 * lib/python/bytes.mjs
 *
 * `repr()` of a Python `bytes` object.
 *
 * The source script prints the value returned by the canonical-JSON encoder,
 * which is `bytes`, so what lands on stdout is not the JSON document but its
 * byte repr: `b'["a","b"]'`. Every rule below is observable in that output.
 */

const HEX_DIGITS = '0123456789abcdef';

const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;
const BACKSLASH = 0x5c;
const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SPACE = 0x20;
const DELETE = 0x7f;

/**
 * Pick the delimiter, matching CPython's "smart quotes" scan.
 *
 * The scan walks the buffer and stops at the first double quote, keeping the
 * single quote; a single quote merely *proposes* the double quote and keeps
 * looking. Net effect: `"` wins as delimiter only when the payload contains an
 * apostrophe and no double quote at all. A JSON array of strings always holds
 * `"`, so in practice this returns the single quote -- but the rule is cheap to
 * implement exactly, so we do.
 */
function chooseQuote(bytes) {
  let quote = SINGLE_QUOTE;
  for (const byte of bytes) {
    if (byte === DOUBLE_QUOTE) return SINGLE_QUOTE;
    if (byte === SINGLE_QUOTE) quote = DOUBLE_QUOTE;
  }
  return quote;
}

/**
 * Render `bytes` exactly as CPython's `repr()` would, including the `b` prefix.
 *
 * Escaping, in priority order: the delimiter and backslash get a backslash;
 * tab / newline / carriage return get their short forms; anything outside the
 * printable ASCII span becomes `\xNN` with lowercase hex -- note that 0x7F is
 * *not* printable, so DEL shows up as `\x7f`; everything else is literal.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function bytesRepr(bytes) {
  const quote = chooseQuote(bytes);
  const parts = ['b', String.fromCharCode(quote)];
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) {
      parts.push('\\', String.fromCharCode(byte));
    } else if (byte === TAB) {
      parts.push('\\t');
    } else if (byte === NEWLINE) {
      parts.push('\\n');
    } else if (byte === CARRIAGE_RETURN) {
      parts.push('\\r');
    } else if (byte < SPACE || byte >= DELETE) {
      parts.push('\\x', HEX_DIGITS[byte >> 4], HEX_DIGITS[byte & 0x0f]);
    } else {
      parts.push(String.fromCharCode(byte));
    }
  }
  parts.push(String.fromCharCode(quote));
  return parts.join('');
}

