/**
 * lib/canonicaljson/escape.mjs
 *
 * String escaping for canonical JSON.
 *
 * The reference encoder runs with ASCII escaping *disabled*, so non-ASCII text
 * stays as literal characters in the document and only becomes multi-byte on
 * the way out through the UTF-8 codec. Observable consequence: 'café' encodes
 * to the bytes `caf\xc3\xa9`, not to `café`.
 */

/** Characters with a dedicated two-character escape. */
const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['"', '\\"'],
  ['\b', '\\b'],
  ['\f', '\\f'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/** Below this, a character must be escaped; at or above it, it is literal. */
const CONTROL_LIMIT = 0x20;

/**
 * Quote and escape a string as a JSON string token.
 *
 * Rules, in order: the seven short escapes above; any remaining control
 * character (U+0000-U+001F, e.g. the vertical tab) as `\u00xx` with lowercase
 * hex; everything else verbatim -- including U+007F, U+2028 and U+2029, which
 * some JS encoders escape but this one must not.
 *
 * @param {string} text
 * @returns {string}
 */
export function escapeJsonString(text) {
  const parts = ['"'];
  for (const character of text) {
    const shortEscape = SHORT_ESCAPES.get(character);
    if (shortEscape !== undefined) {
      parts.push(shortEscape);
      continue;
    }
    const codePoint = character.codePointAt(0);
    if (codePoint < CONTROL_LIMIT) {
      parts.push('\\u', codePoint.toString(16).padStart(4, '0'));
    } else {
      parts.push(character);
    }
  }
  parts.push('"');
  return parts.join('');
}

