/**
 * lib/canonicaljson/encoder.mjs
 *
 * The canonical serialiser: produces the compact, deterministic JSON *text*
 * that lib/canonicaljson/index.mjs then encodes to bytes.
 *
 * "Canonical" here means three things, all reverse-engineered from the
 * reference encoder's observable output:
 *   - no insignificant whitespace: separators are exactly ',' and ':';
 *   - object keys sorted, so the same mapping always yields the same document;
 *   - non-finite floats rejected rather than emitted as bare NaN / Infinity.
 */

import { compareCodePoints } from '../python/text.mjs';
import { formatFloat, formatInteger } from '../python/numbers.mjs';
import { escapeJsonString } from './escape.mjs';

/** Raised for values the canonical form cannot represent. */
export class CanonicalJsonError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CanonicalJsonError';
  }
}

/** Mapping-like inputs the encoder accepts alongside plain objects. */
function entriesOf(value) {
  return value instanceof Map ? [...value.entries()] : Object.entries(value);
}

function encodeNumber(value) {
  if (!Number.isFinite(value)) {
    throw new CanonicalJsonError('Out of range float values are not JSON compliant');
  }
  return Number.isInteger(value) ? formatInteger(value) : formatFloat(value);
}

/**
 * Sort object keys by code point, the ordering Python's `sort_keys` applies.
 *
 * Keys must already be strings: coercing them would let two distinct keys
 * collide and quietly drop data, so a non-string key is an error instead.
 */
function sortEntries(entries) {
  for (const [key] of entries) {
    if (typeof key !== 'string') {
      throw new CanonicalJsonError(`keys must be str, not ${typeof key}`);
    }
  }
  return [...entries].sort(([left], [right]) => compareCodePoints(left, right));
}

/**
 * Serialise a value to canonical JSON text.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function encodeCanonicalText(value) {
  // Tracks the ancestor containers of the value being written, so a container
  // that contains itself is reported rather than overflowing the stack.
  const ancestors = new Set();

  const write = (current) => {
    if (current === null || current === undefined) return 'null';

    switch (typeof current) {
      case 'boolean':
        return current ? 'true' : 'false';
      case 'string':
        return escapeJsonString(current);
      case 'number':
        return encodeNumber(current);
      case 'bigint':
        return formatInteger(current);
      case 'object':
        break;
      default:
        throw new CanonicalJsonError(`Object of type ${typeof current} is not JSON serializable`);
    }

    if (ancestors.has(current)) {
      throw new CanonicalJsonError('Circular reference detected');
    }
    ancestors.add(current);
    try {
      if (Array.isArray(current)) {
        return `[${current.map(write).join(',')}]`;
      }
      const fields = sortEntries(entriesOf(current))
        .map(([key, fieldValue]) => `${escapeJsonString(key)}:${write(fieldValue)}`);
      return `{${fields.join(',')}}`;
    } finally {
      ancestors.delete(current);
    }
  };

  return write(value);
}

