/**
 * lib/cli/help.mjs
 *
 * Usage and help text layout, reproducing `argparse`'s formatter for the
 * option-only parsers this project builds.
 */

/** Column budget constants taken from argparse's HelpFormatter defaults. */
const CURRENT_INDENT = 2;
const MAX_HELP_POSITION = 24;

/** How an action appears in the usage line, e.g. `[-h]` or `--a A`. */
function usageFragment(action) {
  const body = action.nargs === 0
    ? action.optionStrings[0]
    : `${action.optionStrings[0]} ${action.metavar}`;
  return action.required ? body : `[${body}]`;
}

/** How an action appears in the options list, e.g. `-h, --help` or `--a A`. */
function invocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
}

/**
 * Build the `usage: ...` line, without a trailing newline.
 *
 * @param {string} prog
 * @param {object[]} actions
 * @returns {string}
 */
export function formatUsage(prog, actions) {
  return `usage: ${[prog, ...actions.map(usageFragment)].join(' ')}`;
}

/**
 * Build the full `--help` output, terminated by a newline.
 *
 * The help column sits at `min(widest invocation + indent + 2, 24)`; an action
 * with no help text is emitted bare, with no padding after it.
 *
 * @param {string} prog
 * @param {object[]} actions
 * @returns {string}
 */
export function formatHelp(prog, actions) {
  const widest = Math.max(...actions.map((action) => invocation(action).length + CURRENT_INDENT));
  const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);
  const actionWidth = helpPosition - CURRENT_INDENT - 2;

  const lines = [formatUsage(prog, actions), '', 'options:'];
  for (const action of actions) {
    const label = invocation(action);
    if (!action.help) {
      lines.push(`${' '.repeat(CURRENT_INDENT)}${label}`);
    } else if (label.length <= actionWidth) {
      lines.push(`${' '.repeat(CURRENT_INDENT)}${label.padEnd(actionWidth)}  ${action.help}`);
    } else {
      lines.push(`${' '.repeat(CURRENT_INDENT)}${label}`);
      lines.push(`${' '.repeat(helpPosition)}${action.help}`);
    }
  }
  return `${lines.join('\n')}\n`;
}

