#!/usr/bin/env node
/**
 * test7.mjs -- Node.js port of dataset/canonicaljson/test7.py
 *
 * Reads two strings from `--a` / `--b`, then prints the canonical-JSON encoding
 * of the pair twice: once in the order given, once sorted.
 *
 * Both lines print the encoder's *byte string* repr (`b'...'`), because the
 * reference encoder returns bytes and the original script prints that object
 * directly rather than a decoded string.
 */

import { basename } from 'node:path';

import { encodeCanonicalJson } from './lib/canonicaljson/index.mjs';
import { bytesRepr } from './lib/python/bytes.mjs';
import { sortedStrings } from './lib/python/text.mjs';
import { ExitRequest } from './lib/cli/errors.mjs';
import { ArgumentParser } from './lib/cli/parser.mjs';

/** Build the parser: two required string options, plus the automatic help. */
export function buildParser(prog) {
  const parser = new ArgumentParser({ prog });
  parser.addArgument(['--a'], { required: true });
  parser.addArgument(['--b'], { required: true });
  return parser;
}

/**
 * @param {string[]} argv  arguments only, without program name
 * @param {string} prog    name shown in usage and error messages
 */
export function main(argv, prog) {
  const args = buildParser(prog).parseArgs(argv);

  const data = [args.a, args.b];
  const result1 = encodeCanonicalJson(data); // Encode list as canonical JSON
  const result2 = encodeCanonicalJson(sortedStrings(data)); // Encode sorted list as canonical JSON
  console.log(bytesRepr(result1));
  console.log(bytesRepr(result2));
