import { execFileSync } from 'node:child_process';

const REF = '/workspace/dataset/test7_executable';
const NEW = '/output/test7.mjs';

const run = (command, args) => {
  try {
    return { status: 0, out: execFileSync(command[0], [...command.slice(1), ...args], { encoding: 'utf8' }) };
  } catch (e) {
    return { status: e.status, out: (e.stdout ?? '') + (e.stderr ?? '') };
  }
};

// Character pool: ASCII printables, every escapable control char, multi-byte
// UTF-8 at each width, astral pairs, and combining marks.
const pool = [];
for (let c = 0x20; c < 0x7f; c += 1) pool.push(String.fromCharCode(c));
for (let c = 0x01; c < 0x20; c += 1) pool.push(String.fromCharCode(c));
pool.push('\x7f', '', '', '­', '߿', 'ࠀ', '퟿', '', '�', '￿');
pool.push(' ', ' ', '﻿', 'é', 'é', 'ß', 'π', '中', 'あ', 'ﷺ');
pool.push('\u{10000}', '\u{1F600}', '\u{10FFFF}', '\u{1D11E}');

const rng = (seed) => () => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
};
const next = rng(20260807);

const pick = () => pool[Math.floor(next() * pool.length)];
const makeString = () => {
  const length = Math.floor(next() * 9);
  let text = '';
  for (let i = 0; i < length; i += 1) text += pick();
  return text;
};

let failures = 0;
const rounds = 700;
for (let round = 0; round < rounds; round += 1) {
  const a = makeString();
  const b = round % 7 === 0 ? a : makeString(); // exercise the equal-values path
  const args = ['--a', a, '--b', b];
  const expected = run([REF], args);
  const actual = run(['node', NEW], args);
  if (expected.status !== actual.status || expected.out !== actual.out) {
    failures += 1;
    if (failures <= 5) {
      console.log('FAIL', JSON.stringify([a, b]));
      console.log('  expected', JSON.stringify(expected));
      console.log('  actual  ', JSON.stringify(actual));
    }
  }
}

console.log(`\n${rounds - failures}/${rounds} fuzz rounds matched.`);
process.exit(failures === 0 ? 0 : 1);

