/**
 * Self-checks for the library paths the entry point never reaches (nested
 * containers, key sorting, number formatting). The reference executable only
 * ever encodes two strings, so these expectations come from the documented
 * canonical-JSON rules and CPython `repr()` semantics, not from differential
 * testing.
 */
import { encodeCanonicalJson, encodeCanonicalText, CanonicalJsonError } from '/output/lib/canonicaljson/index.mjs';
import { bytesRepr } from '/output/lib/python/bytes.mjs';
import { formatFloat } from '/output/lib/python/numbers.mjs';
import { sortedStrings, compareCodePoints } from '/output/lib/python/text.mjs';

let bad = 0;
const eq = (label, actual, expected) => {
  const ok = actual === expected;
  if (!ok) bad += 1;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${label}: ${actual}${ok ? '' : `  (want ${expected})`}`);
};

eq('key sorting + compact separators',
  encodeCanonicalText({ b: 1, a: 2, A: 3 }), '{"A":3,"a":2,"b":1}');
eq('nested containers',
  encodeCanonicalText({ z: [1, { y: null }], a: true }), '{"a":true,"z":[1,{"y":null}]}');
eq('empty containers', encodeCanonicalText([{}, []]), '[{},[]]');
eq('unicode key sorting',
  encodeCanonicalText({ '\u{1F600}': 1, '￿': 2 }), '{"￿":2,"\u{1F600}":1}');
eq('bigint', encodeCanonicalText({ n: 10n ** 25n }), '{"n":10000000000000000000000000}');
eq('bytes round trip', bytesRepr(encodeCanonicalJson({ k: 'café' })), "b'{\"k\":caf\\xc3\\xa9\"}'".replace('caf', 'caf'));

// CPython repr() switches to scientific notation outside 1e-4 .. 1e16 and pads
// the exponent to two digits -- both differ from plain JS number formatting.
eq('float 1.5', formatFloat(1.5), '1.5');
eq('float 1.0', formatFloat(1.0), '1.0');
eq('float -0.0', formatFloat(-0), '-0.0');
eq('float 1e15', formatFloat(1e15), '1000000000000000.0');
eq('float 1e16', formatFloat(1e16), '1e+16');
eq('float 1e-4', formatFloat(1e-4), '0.0001');
eq('float 1e-5', formatFloat(1e-5), '1e-05');
eq('float 1e21', formatFloat(1e21), '1e+21');
eq('float 0.1+0.2', formatFloat(0.1 + 0.2), '0.30000000000000004');
eq('float 1.5e-7', formatFloat(1.5e-7), '1.5e-07');

const throws = (label, fn, expected) => {
  try {
    fn();
    bad += 1;
    console.log(`FAIL ${label}: no error raised`);
  } catch (e) {
    eq(label, e instanceof CanonicalJsonError ? e.message : `wrong type ${e.name}`, expected);
  }
};
throws('NaN rejected', () => encodeCanonicalText(NaN), 'Out of range float values are not JSON compliant');
throws('Infinity rejected', () => encodeCanonicalText([Infinity]), 'Out of range float values are not JSON compliant');
throws('cycle rejected', () => { const a = []; a.push(a); return encodeCanonicalText(a); }, 'Circular reference detected');

// Code-point ordering, where JS's own `<` disagrees with Python.
eq('U+FFFF sorts before astral', compareCodePoints('￿', '\u{1F600}') < 0, true);
eq('sorted() is stable + ascending', sortedStrings(['b', 'a', 'b', 'A']).join('|'), 'A|a|b|b');

console.log(bad === 0 ? '\nall library self-checks passed' : `\n${bad} self-check(s) failed`);
process.exit(bad === 0 ? 0 : 1);

